import sys, os, json
sys.path.insert(0, r'C:\Users\DELL\Desktop\AI_CAD\Create_Flatten_SheetMetal-main\tools\sheetmetal_kit')
import geom as G
import ezdxf

TMP = r'C:\Users\DELL\AppData\Local\Temp\ai_cad_521127-03'
ORD = r'C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\27-11-2026\521127-03'
TPL = r'C:\Users\DELL\Desktop\AI_CAD\Create_Flatten_SheetMetal-main\templates\Template.dxf'
os.makedirs(TMP + r'\specs', exist_ok=True)
R = 2.0


def rect(w, h, r):
    pts = [(0, 0), (w, 0), (w, h), (0, h)]
    return G.poly(pts, corner={0: r, 1: r, 2: r, 3: r})


def part(code):
    flags = []
    if code in ('26-072690', '26-072693'):
        w, h = 50.0, 32.0
        e = rect(w, h, R)
        e += [G.C((10, 12), 6.8), G.C((40, 12), 6.8)]
        e += [G.L((0, 22), (50, 22), color=1), G.L((0, 28), (50, 28), color=1)]
    elif code in ('26-072691', '26-072694'):
        w, h = 88.0, 50.0
        e = rect(w, h, R)
    elif code == '26-072692':
        w, h = 50.0, 38.0
        e = rect(w, h, R)
        e += [G.C((10, 10), 9), G.C((40, 10), 9)]
        e += [G.L((0, 27), (50, 27), color=1), G.L((0, 33), (50, 33), color=1)]
        flags = ['1. Chân dim kích thước bị lệch (lỗ φ9 trang 3: dim 28 chỉ vào mép tấm A 32 hoặc mép tấm C 33, vẽ theo mép C 33, lỗ cách mép C 10)']
    elif code == '26-072695':
        w, h = 50.0, 38.0
        e = rect(w, h, R)
        e += [G.C((10, 28), 9), G.C((40, 28), 9)]
        e += [G.L((0, 5), (50, 5), color=1), G.L((0, 11), (50, 11), color=1)]
    elif code == '26-071801':
        w, h = 66.5, 60.0
        e = rect(w, h, R)
        e += [G.C((8.25, 8), 9), G.C((58.25, 8), 9)]
    else:
        raise SystemExit('ma khong ho tro ' + code)
    return w, h, e, flags


def write_dxf(code, ents, path):
    d = ezdxf.readfile(TPL)
    ms = d.modelspace()
    for e in ents:
        t = e['t']
        at = {'layer': '0'}
        if e.get('color'):
            at['color'] = e['color']
        if t == 'LINE':
            ms.add_line(tuple(e['p1']), tuple(e['p2']), dxfattribs=at)
        elif t == 'ARC':
            ms.add_arc(tuple(e['c']), e['r'], e['a0'], e['a1'], dxfattribs=at)
        elif t == 'CIRCLE':
            ms.add_circle(tuple(e['c']), e['r'], dxfattribs=at)
        elif t == 'POINT':
            ms.add_point(tuple(e['p']), dxfattribs=at)
    d.saveas(path)


def from_existing(code, w):
    d = ezdxf.readfile(ORD + '\\' + code + '.dxf')
    ents = []
    for x in d.modelspace():
        if x.dxftype() == 'CIRCLE':
            ents.append({'t': 'CIRCLE', 'c': [x.dxf.center.x, x.dxf.center.y], 'r': x.dxf.radius})
    return ents


if __name__ == '__main__':
    code = sys.argv[1]
    if code == 'existing':
        for c, w in (('26-072632', 130.0), ('26-072633', 204.0), ('26-072634', 97.6)):
            ents = from_existing(c, w)
            G.save_spec(TMP + r'\specs\spec_%s.json' % c, c, ents, w, w, [])
        print('ok existing specs')
    else:
        w, h, e, flags = part(code)
        e, bw, bh = (lambda r: (r[0], r[1], r[2]))(G.place(e)) if False else (e, w, h)
        G.save_spec(TMP + r'\specs\spec_%s.json' % code, code, e, w, h, flags)
        write_dxf(code, e, ORD + '\\' + code + '.dxf')
        print('built', code, w, 'x', h, 'entities', len(e))

