def write_dxf(code, ents, path):
    d = ezdxf.readfile(TPL)
    ms = d.modelspace()
    for e in ents:
        t = e['t']
        at = {'layer': '0'}
        if e.get('color'):
            at['color'] = e['color']
        if t == 'LINE':
            ms.add_line(tuple(e['p1']), tuple(e['p2']), dxfattribs=at)
        elif t == 'ARC':
            ms.add_arc(tuple(e['c']), e['r'], e['a0'], e['a1'], dxfattribs=at)
        elif t == 'CIRCLE':
            ms.add_circle(tuple(e['c']), e['r'], dxfattribs=at)
        elif t == 'POINT':
            ms.add_point(tuple(e['p']), dxfattribs=at)
    d.saveas(path)


def from_existing(code, w):
    d = ezdxf.readfile(ORD + '\\' + code + '.dxf')
    ents = []
    for x in d.modelspace():
        if x.dxftype() == 'CIRCLE':
            ents.append({'t': 'CIRCLE', 'c': [x.dxf.center.x, x.dxf.center.y], 'r': x.dxf.radius})
    return ents


